const SWIPER_DEFAULTS = {
  grabCursor: !0,
  autoplay: { delay: 6e3, disableOnInteraction: !1, pauseOnMouseEnter: !0 },
  keyboard: { enabled: !0 },
};
document.addEventListener("DOMContentLoaded", () => {
  typeof Swiper > "u" ||
    (initWildlifeCarousel(),
    initPillarsCarousel(),
    initNomaCarousel(),
    initCulinaryCarousel(),
    initEchoesCarousel());
});
function initWildlifeCarousel() {
  if (!document.querySelector(".wildlife-swiper")) return;
  const i = document.querySelectorAll("#wildlife-dots .carousel-dot");
  function r(t) {
    i.forEach((e, a) => {
      e.classList.toggle("carousel-dot--active", a === t);
    });
  }
  const n = new Swiper(".wildlife-swiper", {
    ...SWIPER_DEFAULTS,
    effect: "coverflow",
    centeredSlides: !0,
    slidesPerView: 1,
    loop: !0,
    coverflowEffect: {
      rotate: 20,
      stretch: 0,
      depth: 100,
      modifier: 1,
      scale: 1,
      slideShadows: !0,
    },
    breakpoints: { 900: { slidesPerView: 2 } },
    navigation: {
      nextEl: ".swiper-button-next-custom",
      prevEl: ".swiper-button-prev-custom",
    },
    on: {
      slideChange: function () {
        const t = this.realIndex % 3;
        (document.querySelectorAll(".desc-panel").forEach((e) => {
          (e.classList.remove("swiper-desc-active"),
            parseInt(e.dataset.index, 10) === t &&
              e.classList.add("swiper-desc-active"));
        }),
          r(t));
      },
    },
  });
  (i.forEach((t, e) => {
    t.addEventListener("click", () => {
      n.slideToLoop(e);
    });
  }),
    r(n.realIndex % 3));
}
function initPillarsCarousel() {
  document.querySelector(".pillars-swiper") &&
    new Swiper(".pillars-swiper", {
      ...SWIPER_DEFAULTS,
      effect: "slide",
      freeMode: { enabled: !0, sticky: !0 },
      speed: 500,
      spaceBetween: 30,
      loop: !0,
      navigation: { nextEl: ".pillars-nav-next", prevEl: ".pillars-nav-prev" },
      pagination: { el: ".pillars-pagination", clickable: !0 },
    });
}
function initNomaCarousel() {
  document.querySelector(".noma-around-swiper") &&
    new Swiper(".noma-around-swiper", {
      ...SWIPER_DEFAULTS,
      autoplay: { ...SWIPER_DEFAULTS.autoplay, delay: 5e3 },
      slidesPerView: 1,
      spaceBetween: 24,
      loop: !1,
      breakpoints: { 768: { slidesPerView: 2, spaceBetween: 32 } },
      pagination: { el: ".noma-around-pagination", clickable: !0 },
    });
}
function initCulinaryCarousel() {
  document.querySelector(".gast-culinary-swiper") &&
    new Swiper(".gast-culinary-swiper", {
      ...SWIPER_DEFAULTS,
      autoplay: { ...SWIPER_DEFAULTS.autoplay, delay: 4500 },
      effect: "slide",
      freeMode: { enabled: !0, sticky: !0 },
      slidesPerView: 1,
      spaceBetween: 0,
      loop: !0,
      pagination: { el: ".gast-culinary-pagination", clickable: !0 },
    });
}
function initEchoesCarousel() {
  document.querySelector(".cult-echoes-swiper") &&
    new Swiper(".cult-echoes-swiper", {
      ...SWIPER_DEFAULTS,
      autoplay: !1,
      effect: "slide",
      freeMode: { enabled: !0, sticky: !1 },
      slidesPerView: "auto",
      spaceBetween: 16,
      pagination: { el: ".cult-echoes-pagination", clickable: !0 },
      breakpoints: { 0: { spaceBetween: 12 }, 768: { spaceBetween: 16 } },
    });
}
